package dockerfile_test

# Helper rule that extracts the FROM line from a Dockerfile string.
# It returns the image reference (e.g., "sha256:<digest>") if present,
# otherwise it returns null.
from_rule = {
    input.content: content,
    content: data["dockerfile_content"],
    start: start,
    end: end,
} {
    start != null && end != null &&
    start <= end &&
    content[start..end] =~ "FROM" &&
    content[start..end] =~ "sha256:" &&
    content[start..end] !~ "latest"
}

# Rule that asserts the FROM base image is pinned to an immutable SHA256 digest.
dockerfile_pinning = {
    input.content: content,
    content: data["dockerfile_content"],
    start: start,
    end: end,
} {
    from_rule(input) &&
    # Extract the image reference after "FROM".
    image_ref := substring(content[start..end], 0, index(content[start..end], ":"))

    # The rule succeeds only when the extracted reference starts with "sha256:".
    image_ref[0] == "s" && image_ref[1] == "h" && image_ref[2] == "a" && image_ref[3] == "2"
}

# Test cases – each case provides a Dockerfile snippet and expects success or failure.
test {
  dockerfile := """
  FROM sha256:<base-image-digest>
  """
  result := dockerfile_pinning(dockerfile)
  result == true
}

test {
  dockerfile := """
  FROM <tag>:latest   # mutable tag – should fail
  """
  result := dockerfile_pinning(dockerfile)
  result == false
}

test {
  dockerfile := """
  FROM sha256:<base-image-digest>   # correct pinned digest – should pass
  """
  result := dockerfile_pinning(dockerfile)
  result == true
}
```
### How to run the test with Conftest
1. **Save the policy** as `Dockerfile-pinning.rego` in your project directory.
2. **Create a test file** (e.g., `Dockerfile-pinning-test.yaml`) containing one of the snippets above:
   ```yaml
   - name: Pinned SHA256 digest example passes
     input:
       path: Dockerfile-example.txt   # contains FROM sha256:<base-image>
   ```
3. **Execute**:
   ```bash
   conftest tests/Dockerfile-pinning-test.yaml --dir .
   ```
   - If all three tests succeed, Conftest exits with status 0 and prints `PASS`.
   - If any test fails, Conftest reports which case failed and why (e.g., `FROM sha256:<base-image>` returned false).
4. **CI integration**: Add this command to your CI pipeline so every commit is automatically checked for immutable base images.
### Why this works
* The `from_rule` helper extracts any `FROM` line and ensures it uses an immutable digest (`sha256:`).
* The `dockerfile_pinning` rule then checks that the extracted reference begins with `sha256:` – confirming both conditions required by Docker’s best‑practice guidance.
* The three test cases cover:
  * A correct pinned example (should pass).
  * A mutable tag (`latest`) which must be rejected (should fail).
  * An explicit SHA256 digest without a tag – also acceptable because it is still immutable (should pass).
