                    echo "$RESULTS" | jq '.issues[] | select(.status=="ERROR")' > /tmp/errors.txt || true
                    if [ $(cat /tmp/errors.txt | wc -l) -gt 0 ]; then
                        echo "Static analysis failed – errors found:"
                        cat /tmp/errors.txt
                        exit 1   # Fail the pipeline immediately
                    fi
                    # Optional: check coverage threshold (e.g., >= 85%)
                    COVERAGE=$(echo "$RESULTS" | jq '.issues[] | select(.status=="ERROR") | .ruleId' | wc -l)
